/**
 * kharij-tax-calculator.js
 *
 * Tax collection auto-calculator for Kharij forms.
 * Calculates total demand, arrears, converts amounts to Bengali words,
 * auto-generates dakhila_serial from date, and converts English dates
 * to Bengali calendar dates.
 *
 * Depends on:
 *   - kharij-utils.js (bnToEn, toBnNum, parseNum)
 *   - amount-to-bangla-words.js (bnNumToWords)
 *   - bangla-calendar.js (gregorianToBangla)
 *
 * Provides:
 *   - calcTaxTotals()        – Auto-calculate tax demand/arrears/words
 *   - autoGenerateDakhilaSerial() – Generate serial from date
 *   - updateBanglaDate()     – Convert English date to Bengali
 *   - autoFillTaxReceiptFromDate() – Fill all tax receipt fields from date
 */
(function () {
  'use strict';

  const taxFields = [
    'tax_arrears_over_3_years',
    'tax_arrears_last_3_years',
    'tax_penalty',
    'tax_current_demand',
    'tax_total_collected',
    'tax_total_demand',
  ];

  function parseTaxVal(id) {
    const el = document.getElementById(id);
    if (!el) return 0;
    const bnToEn = window.bnToEn || function (s) { return s; };
    return parseFloat(bnToEn(el.value).replace(/[^0-9.]/g, '')) || 0;
  }

  function calcTaxTotals() {
    const d = parseTaxVal('tax_arrears_over_3_years') +
            parseTaxVal('tax_arrears_last_3_years') +
            parseTaxVal('tax_penalty') +
            parseTaxVal('tax_current_demand');
    const c = parseTaxVal('tax_total_collected');
    const a = d - c;

    const tdEl = document.getElementById('tax_total_demand');
    const taEl = document.getElementById('tax_total_arrears');
    const twEl = document.getElementById('total_amount_words');

    // Always auto-fill totals (live as user types)
    if (tdEl) tdEl.value = d > 0 ? d.toString() : '';
    if (taEl) taEl.value = a >= 0 ? a.toString() : a.toString();

    // Always update Bengali words
    if (twEl && typeof window.bnNumToWords === 'function') {
      const demandVal = parseFloat(tdEl ? tdEl.value : d) || d;
      if (demandVal > 0) {
        twEl.value = window.bnNumToWords(demandVal);
      } else {
        twEl.value = '';
      }
    }
  }

  /**
   * Extract year from a date string (dd-mm-yyyy or dd/mm/yyyy).
   */
  function extractYear(dateStr) {
    if (!dateStr) return '';
    const parts = dateStr.split(/[-/]/);
    if (parts.length === 3) {
      const y = parseInt(parts[2], 10);
      if (!isNaN(y) && y >= 1000) return y.toString();
    }
    const yrMatch = dateStr.match(/(\d{4})$/);
    return yrMatch ? yrMatch[1] : '';
  }

  // Sequential counter for auto-generating dakhila_serial
  let dakhilaSerialCounter = 1;

  function autoGenerateDakhilaSerial() {
    const enEl = document.getElementById('receipt_date_en');
    const serialEl = document.getElementById('dakhila_serial');
    if (!enEl || !serialEl) return;
    const bnToEn = window.bnToEn || function (s) { return s; };
    const toBnNum = window.toBnNum || function (s) { return s; };
    const enVal = bnToEn(enEl.value.trim());
    if (!enVal) return;
    // Only auto-generate if dakhila_serial is empty
    if (serialEl.value.trim()) return;

    let year = '';

    // Try dd-mm-yyyy format
    const parts = enVal.split(/[-/]/);
    if (parts.length === 3) {
      const d = parseInt(parts[0], 10);
      const m = parseInt(parts[1], 10);
      const y = parseInt(parts[2], 10);
      if (!isNaN(d) && !isNaN(m) && !isNaN(y) && y >= 1000) {
        year = y.toString();
      }
    }

    // Try "dd MonthName, yyyy" format
    if (!year) {
      const yrMatch = enVal.match(/(\d{4})$/);
      if (yrMatch) year = yrMatch[1];
    }

    if (!year) return;

    // First 2 digits = last 2 digits of the year
    const lastTwo = year.slice(-2);
    // Remaining 10 digits = sequential counter, zero-padded
    const suffix = ('0000000000' + dakhilaSerialCounter).slice(-10);
    dakhilaSerialCounter++;

    // Convert to Bengali digits
    const serialNum = lastTwo + suffix;
    serialEl.value = toBnNum(serialNum);
  }

  function updateBanglaDate() {
    const enEl = document.getElementById('receipt_date_en');
    const bnEl = document.getElementById('receipt_date');
    if (!enEl || !bnEl) return;
    const enVal = enEl.value.trim();
    if (!enVal) return;
    if (typeof window.gregorianToBangla === 'function') {
      const banglaDate = window.gregorianToBangla(enVal);
      if (banglaDate && (!bnEl.value || bnEl.value.indexOf('\u0997\u09CD\u09B0\u09C7\u0997\u09B0\u09BF\u09AF\u09BC') === -1)) {
        bnEl.value = banglaDate;
      }
    }
  }

  /**
   * Auto-fill all tax receipt fields based on the English Date value.
   * When English Date is filled: generates holding_number, challan_number,
   * last_payment_year, and tax amounts from the date's year.
   * When English Date is cleared: clears Bangla date and last_payment_year.
   */
  function autoFillTaxReceiptFromDate() {
    const enEl = document.getElementById('receipt_date_en');
    if (!enEl) return;

    const enVal = enEl.value.trim();

    if (!enVal) {
      // English Date cleared → clear Bangla date and last_payment_year
      var bnEl = document.getElementById('receipt_date');
      var pyEl = document.getElementById('last_payment_year');
      if (bnEl) bnEl.value = '';
      if (pyEl) pyEl.value = '';
      return;
    }

    // Extract year from date
    const bnToEn = window.bnToEn || function (s) { return s; };
    const cleanVal = bnToEn(enVal);
    const year = extractYear(cleanVal);
    if (!year) return;

    const nextYear = String(parseInt(year, 10) + 1);
    const shortYear = year.slice(-2);
    const nextShort = nextYear.slice(-2);

    // Generate deterministic variation based on date
    const parts = cleanVal.split(/[-/]/);
    const day = parts.length === 3 ? parseInt(parts[0], 10) || 1 : 1;
    const month = parts.length === 3 ? parseInt(parts[1], 10) || 1 : 1;
    const seed = ((day * month) % 100) || 1;

    // Generate field values (using English digits throughout)
    function fill(id, val) {
      var el = document.getElementById(id);
      if (el) el.value = val;
    }

    fill('last_payment_year', year + '-' + nextYear);

    var holdingNum = year + '-' + (100000 + seed);
    fill('holding_number', holdingNum);

    var challanNum = shortYear + nextShort + '-' + String(571100000 + seed).slice(-10);
    fill('challan_number', challanNum);

    // Generate tax amounts with date-based variation
    var arrearsOver3 = String(50 + (seed % 150));
    var arrearsLast3 = String(20 + (seed % 80));
    var penalty = String(10 + (seed % 140));
    var currentDemand = String(5 + (seed % 75));
    var totalDemand = String(
      parseInt(arrearsOver3, 10) +
      parseInt(arrearsLast3, 10) +
      parseInt(penalty, 10) +
      parseInt(currentDemand, 10)
    );
    var totalCollected = totalDemand;

    fill('tax_arrears_over_3_years', arrearsOver3);
    fill('tax_arrears_last_3_years', arrearsLast3);
    fill('tax_penalty', penalty);
    fill('tax_current_demand', currentDemand);
    fill('tax_total_demand', totalDemand);
    fill('tax_total_collected', totalCollected);
    fill('tax_total_arrears', '0');
    fill('tax_remarks', '');

    // Update Bangla date and dakhila serial
    updateBanglaDate();
    autoGenerateDakhilaSerial();

    // Calculate totals and update live preview
    calcTaxTotals();
  }

  /**
   * On initial page load, if receipt_date_en has a value, populate
   * receipt_date (Bangla) and last_payment_year from the English date.
   * Only fills these two fields — does not overwrite other saved tax data.
   */
  function initBanglaDateAndPaymentYear() {
    var enEl = document.getElementById('receipt_date_en');
    if (!enEl) return;
    var enVal = enEl.value.trim();
    if (!enVal) return;

    // Fill Bangla date from English date
    updateBanglaDate();

    // Fill last_payment_year from extracted year
    var bnToEn = window.bnToEn || function (s) { return s; };
    var cleanVal = bnToEn(enVal);
    var year = extractYear(cleanVal);
    if (year) {
      var pyEl = document.getElementById('last_payment_year');
      var nextYear = String(parseInt(year, 10) + 1);
      if (pyEl && !pyEl.value) {
        pyEl.value = year + '-' + nextYear;
      }
    }
  }

  function initTaxCalculator() {
    // Attach listeners to tax fields
    taxFields.forEach(function (id) {
      var el = document.getElementById(id);
      if (el) {
        el.addEventListener('input', calcTaxTotals);
        el.addEventListener('change', calcTaxTotals);
      }
    });

    // Listen for English date changes → auto-fill Bangla date, payment year, and all tax fields
    var enDateEl = document.getElementById('receipt_date_en');
    if (enDateEl) {
      // Live fill as user types (Bangla date + last_payment_year update on each keystroke;
      // full auto-fill triggers once date is complete enough to extract year)
      enDateEl.addEventListener('input', autoFillTaxReceiptFromDate);
      enDateEl.addEventListener('change', autoFillTaxReceiptFromDate);
      enDateEl.addEventListener('blur', autoFillTaxReceiptFromDate);
    }

    // Initial population of receipt_date and last_payment_year
    // (important for edit mode where English date is pre-filled)
    setTimeout(initBanglaDateAndPaymentYear, 100);

    // Initial calculation
    setTimeout(calcTaxTotals, 300);

    // Button listener
    var calcBtn = document.getElementById('calcTaxTotals');
    if (calcBtn) calcBtn.addEventListener('click', calcTaxTotals);
  }

  // Expose functions globally for other scripts (e.g., random fill, sample data buttons)
  window.calcTaxTotals = calcTaxTotals;
  window.initBanglaDateAndPaymentYear = initBanglaDateAndPaymentYear;

  // Auto-init
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initTaxCalculator);
  } else {
    initTaxCalculator();
  }
})();
